head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS10400.xml';
scwin.vMktactCd = '305'; //채권시장조치구분코드				
scwin.vIsuCd = '', scwin.hasAttachDoc = '';
scwin.gBndApplId, scwin.gProcsStat = '';
scwin.vBndListProcsTpCd = 1; //채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp; //접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9
scwin.vIsurCd = '', scwin.vStripAmtCfm = '';
scwin.vRegYn = 'N';
scwin.btnStat = new Object();
scwin.vViewYN = 'N';
scwin.vRowPos = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명  	 : fn_list_sync
 * 설명       : 목록조회
 ***********************************************/
scwin.fn_list_sync = function() {
    var dsNm = 'BNS_APPL_ACPT_LIST';
    var qryId = 'lds.stf.bnscommon.select.listApplAndAcpt';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    if (scwin.vBndListProcsTpCd == 1) {
        $c.cm.ShowWin(grd_List1);
    } else {
        $c.cm.ShowWin(grd_List2);
    }
};



/********************************************** 
 * 함수명  	 : fn_dtl_sync
 * 설명       : 상세조회
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var dsNm = 'BNS_ISU_CHG_INFO';
    var qryId = 'lds.stf.bnsisuchg.select.readIsuChgInfoAmtMmDdAdd';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    param += '&{P}V_BND_APPL_ID=' + scwin.gBndApplId;
    param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};


/********************************************** 
 * 함수명  	 : fn_addPub_sync
 * 설명       : 추가발행내역 조회
 ***********************************************/
scwin.fn_addPub_sync = function() {
    var dsNm = 'BNS_ADD_PUB_DESC';
    var qryId = 'lds.stf.bnsisuchg.select.listAddPubDesc';
    var param = '&{P}V_ISU_CD=' + scwin.vIsuCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_AddHistory, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_StripAmtCheck
 * 설명      : 2006년 이전이거나 발행된 만기 3년이상 국고채권이 아닌경우 미분류 잔액이 존재안함 
 * 5년물에서 3년물로 수정 jackal_150127
 ***********************************************/
scwin.fn_StripAmtCheck = function() {
    scwin.vIsurCd = dts_DtlInfo.getCellData(dts_DtlInfo.getRowPosition(), "ISUR_NM");
    if (scwin.vIsurCd.substring(0, 5) == "GB035") {
        var vAddIsuDd = Number($c.stf.getObjectValue(edt_AddIsuDd));
        var vExprTerm = (Number($c.stf.getObjectValue(edt_RedmptDd)) - Number($c.stf.getObjectValue(edt_IsuDd))) / 10000;
        if ((vAddIsuDd < 20060101) || (vExprTerm < 3)) {
            var vStripBal = $c.stf.getObjectValue(edt_AfchgStripNsprtBal);
            if (!((vStripBal == null) || (vStripBal == "") || (vStripBal == "0"))) {
                $c.win.alert("스트립미분리잔액은 2006년 이후 발행된 만기 3년이상 국고채권만 해당됩니다.\n시스템 담당자에게 해당종목을 문의하십시요.");
                return false;
            }
        }
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    if ($c.stf.getObjectValue(edt_StrtDd) == '') {
        $c.win.alert("[적용일]을 입력하십시오.");
        edt_StrtDd.focus();
        return false;
    }
    if ($c.bns.fn_CheckDateObj(edt_StrtDd, "적용일")) {
        return false;
    }
    if ($c.stf.getObjectValue(edt_AddCoupnRt) == '') {
        $c.win.alert("[낙찰금리]를 입력하십시오.");
        edt_AddCoupnRt.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_AddIsuDd) == '') {
        $c.win.alert("[추가발행일]를 입력하십시오.");
        edt_AddIsuDd.focus();
        return false;
    }
    if ($c.bns.fn_CheckDateObj(edt_AddIsuDd, "추가발행일")) {
        return false;
    }
    if ($c.stf.getObjectValue(edt_AddIsuAmt) == '') {
        $c.win.alert("[추가발행금액]를 입력하십시오.");
        edt_AddIsuAmt.focus();
        return false;
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_AcptProcsCheck
 * 설명      : 접수, 처리완료시 공통 체크 구문
 ***********************************************/
scwin.fn_AcptProcsCheck = function() {
    //스트립미분리잔액 체크
    if (scwin.fn_StripAmtCheck() == false) return 1;

    //필수입력값 체크
    if (scwin.fn_InputCheck() == false) return 1;

    //적용일,매매일,마감일,채권마감 체크		
    if ($c.bns.fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd), scwin.gBndApplId) > 0) return 1;
    scwin.vIsuCd = dts_DtlInfo.getCellData(1, "ISU_CD");
    scwin.hasAttachDoc = dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC");

    //변경된 데이터가 없더라도 데이터셋 전송
    dts_DtlInfo.UseChangeInfo = "False";
    return 0;
};


/********************************************** 
 * 함수명   : fn_Acpt
 * 설명       : 신청데이터를 접수 처리한다.
 ***********************************************/
scwin.fn_Acpt = function() {
    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck() > 0) return;

    //복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRule(scwin.vScrenID, dts_Temp, scwin.vIsuCd, scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd)) > 0) return;

    //첨부문서 체크
    if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '접수')) return;

    //추가상장 수수료
    scwin.fn_GetPar = fn_GetAddBndListFee;
    scwin.fn_SetPar = fn_SetAddBndListFee;
    $c.bns.fn_PopAddListFee(grd_List1);
    if (scwin.vRegYn == "N") return;
    var url = "/bns/IsuChgAmt.do?method=processApplAcpt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    url += "&REG_YN=" + scwin.vRegYn;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo, I:pInput2=dts_AddListFee)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 처리완료 및 수정을 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck() > 0) return;

    //복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRuleProcEnd(scwin.vScrenID, dts_Temp, scwin.vIsuCd, scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd)) > 0) return;
    var url;
    var vStripProcCfmCnt = 0;
    if (scwin.processGp == '4') {
        //접수 후 수정 및 반송시 체크한다.			
        if ($c.bns.fn_CheckModAndRet(scwin.vScrenID, dts_CheckCmData, scwin.gBndApplId) > 0) return;
        if (!confirm("수정처리 하시겠습니까?")) return;
        url = "/bns/IsuChgAmt.do?method=updateAcpt";
    } else {
        if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '처리완료')) return;
        //스트립 추가/재결합 처리완료 여부 확인
        $c.bns.fn_CheckAcptProcStripProcCfm(dts_StripProcCfm, $c.stf.getObjectValue(edt_StrtDd), scwin.gBndApplId, scwin.vIsuCd, scwin.vBndListProcsTpCd);
        vStripProcCfmCnt = dts_StripProcCfm.getCellData(1, "VALUE");
        //추가상장/스트립 동시 시장조치 금액확인 팝업 호출
        if (vStripProcCfmCnt > 0) {
            scwin.fn_GetPar = fn_GetAddAndStripMktactAmtCfm;
            scwin.fn_SetPar = fn_SetRegYnReturn;
            $c.bns.fn_PopAddAndStripMktactAmtCfm(grd_List1);
            if (scwin.vRegYn != "Y") return; // jackal_15_01_08
        }
        url = "/bns/IsuChgAmt.do?method=processAcptProcessComplt";
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    url += "&REG_YN=" + scwin.vRegYn;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    if (vStripProcCfmCnt > 0) {
        trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo, I:pInput2=dts_AddAndStrip)";
    } else {
        trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    }
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        //첨부문서 목록 팝업	
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetReturn
 * 설명       : 반송 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetReturn = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISUR_NM: dts_DtlInfo.getCellData(1, "ISUR_NM"),
        ISU_NM: dts_DtlInfo.getCellData(1, "ISU_NM")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetReturn
 * 설명       : 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetReturn = function(arrPar) {
    if ("Y" == arrPar[0].SUCCESS_YN) {
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_DtlInfo.getCellData(1, "ISU_CD"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParApprovFileWrt
 * 설명       : 결재파일생성 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParApprovFileWrt = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.gBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        BND_MKTACT_TP_CD: scwin.vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SetProcSaveHeader
 * 설명       : 팝업 데이터를 넘겨받을 데이터셋 헤더 설정
 ***********************************************/
scwin.fn_SetProcSaveHeader = function() {
    dts_AddAndStrip.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_ADD_AND_STRIP_INTEG";
    dts_AddAndStrip.Reset();
};

/********************************************** 
 * 함수명   : fn_GetAddAndStripMktactAmtCfm
 * 설명       : 추가상장/스트립 동시 시장조치 금액확인 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetAddAndStripMktactAmtCfm = function(arrPar) {
    arrPar[0] = {
        VIEW_YN: scwin.vStripAmtCfm,
        BND_MKTACT_TP_CD: scwin.vMktactCd,
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD"),
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        ADD_ISU_AMT: dts_DtlInfo.getCellData(1, "ADD_ISU_AMT"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetRegYnReturn
 * 설명       : 추가상장/스트립 동시 시장조치 금액확인 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetRegYnReturn = function(arrPar) {
    scwin.vRegYn = arrPar[0].REG_YN;
};


/********************************************** 
 * 함수명   : fn_SetSaveHeader
 * 설명       : 팝업 데이터를 넘겨받을 데이터셋 헤더 설정
 ***********************************************/
scwin.fn_SetSaveHeader = function() {
    dts_AddListFee.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_ADD_ANULFEE_INSERT_INFO";
    dts_AddListFee.Reset();
};

/********************************************** 
 * 함수명   : fn_GetAddBndListFee
 * 설명       : 추가상장 수수료 등록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetAddBndListFee = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        MKTACT_TP_CD: scwin.vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetAddBndListFee
 * 설명       : 추가상장 수수료 등록 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetAddBndListFee = function(arrPar) {
    scwin.vRegYn = arrPar[0].REG_YN;
};


/********************************************** 
 * 함수명   : fn_ProcBtnStat
 * 설명       : 처리 상태가 처리완료일 경우, 처리완료 버튼 비활성화
 ***********************************************/
scwin.fn_ProcBtnStat = function() {
    if (scwin.gProcsStat == "처리완료") {
        btn_Proc.src = "../img/bns/btn_20_d.gif";
        scwin.btnStat.Proc = "dis";
    } else {
        btn_Proc.src = "../img/bns/btn_20.gif";
        scwin.btnStat.Proc = "en";
    }
};



/********************************************** 
 * 함수명  	 : fn_ChgTab_Act
 * 설명       : 필드 ReadOnly 속성 제거/부여
 ***********************************************/
scwin.fn_ChgTab_Act = function(vBndListProcsTpCd) {
    //낙찰금리, 추가발행일, 추가발행금액
    if (scwin.vBndListProcsTpCd == 1) {
        edt_AddCoupnRt.setReadOnly("true");
        edt_AddIsuDd.setReadOnly("true");
        $c.stf.showObj(img_AddIsuDd, false); //추가발행일 달력
        edt_AddIsuAmt.setReadOnly("true");
    } else if (scwin.vBndListProcsTpCd == 2) {
        edt_AddCoupnRt.setReadOnly("false");
        edt_AddIsuDd.setReadOnly("false");
        $c.stf.showObj(img_AddIsuDd, true); //추가발행일 달력
        edt_AddIsuAmt.setReadOnly("false");
    }
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(pnl_Req); //패널라운드처리(신청)
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo); //패널라운드처리(상세)
    $c.bns.BnsPanelToGroupBox(pnl_Acpt); //패널라운드처리(접수)

    tab_List.setSelectedTabIndex(1);
    scwin.fn_list_sync(); //목록 조회

    //팀장확인데이터셋설정	

    //dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Temp.insertRow();
    //필드 ReadOnly 속성 제거/부여
    scwin.fn_ChgTab_Act(scwin.vBndListProcsTpCd);

    //추가상장 수수료 등록 데이터셋설정
    scwin.fn_SetSaveHeader();
    //동시시장조치 데이터셋설정
